	/**
	 * Default Constructor
	 */
    public FeatureService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new FeatureEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(FeatureRepository.class) );
		this.validator		= applicationContext.getBean(FeatureValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Feature
	 */
		public Feature createFeature( CreateFeatureCommand command ) {

		Feature entity = new Feature();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setFeatureId( command.getFeatureId() );
            entity.setName( command.getName() );
            entity.setDescription( command.getDescription() );
            entity.setDataType( command.getDataType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Feature {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateFeatureCommand
	 * @return		Feature
	 */
	public Feature updateFeature( UpdateFeatureCommand command ) {

		Feature entity = new Feature();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setFeatureId( command.getFeatureId() );
            entity.setName( command.getName() );
            entity.setDescription( command.getDescription() );
            entity.setFeatureSet( command.getFeatureSet() );
            entity.setSourceDatasets( command.getSourceDatasets() );
            entity.setModels( command.getModels() );
            entity.setTrainingRuns( command.getTrainingRuns() );
            entity.setDataType( command.getDataType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Feature {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteFeatureCommand
	 */
	public void delete( DeleteFeatureCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getFeatureId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Feature {0} ", id );

	}

	/**
	 * Method to retrieve the Feature via FeatureFetchOneSummary
	 * @param 	summary FeatureFetchOneSummary
	 * @return 	FeatureFetchOneResponse
	 */
	public Feature getFeature( FeatureFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "FeatureFetchOneSummary arg cannot be null" );

		Feature entity = null;
		UUID id = summary.getFeatureId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Feature using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Features
	 *
	 * @return 	List<Feature>
	 */
    public List<Feature> getAllFeature() {
		List<Feature> list = projector.findAll( new FindAllFeatureQuery() );
		return list;
	}

	/**
	 * assign FeatureSet on Feature
	 * @param		command AssignFeatureSetToFeatureCommand
	 */
	public void assignFeatureSet( AssignFeatureSetToFeatureCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignFeatureSet(command.getFeatureId(), command.getAssignment());

	}

	/**
	 * unAssign FeatureSet on Feature
	 * @param		command UnAssignFeatureSetFromFeatureCommand
	 */
	public void unAssignFeatureSet( UnAssignFeatureSetFromFeatureCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignFeatureSet(command.getFeatureId());
	}
	

